package com.charles.trailsage.data.local

import androidx.room.Entity
import androidx.room.PrimaryKey

@Entity("setup_status")
data class SetupStatusEntity(@PrimaryKey val id: Int = 1, val state: String = "NOT_STARTED", val setupComplete: Boolean = false, val currentStep: String = "", val lastError: String? = null, val updatedAt: Long = System.currentTimeMillis())
@Entity("required_assets")
data class RequiredAssetEntity(@PrimaryKey val id: String, val name: String, val type: String, val version: String, val downloadUrl: String, val localPath: String, val sizeBytes: Long, val checksumSha256: String, val required: Boolean, val installed: Boolean = false, val verified: Boolean = false, val demoPlaceholder: Boolean = false, val license: String = "", val attribution: String = "", val minAndroidSdk: Int = 26, val recommendedRamMb: Int = 0, val engine: String = "", val createdAt: Long = System.currentTimeMillis(), val updatedAt: Long = System.currentTimeMillis())
@Entity("downloaded_assets")
data class DownloadedAssetEntity(@PrimaryKey val id: String, val assetId: String, val localPath: String, val sizeBytes: Long, val verified: Boolean, val installedAt: Long)
@Entity("asset_checksums")
data class AssetChecksumEntity(@PrimaryKey val assetId: String, val checksumSha256: String, val verifiedAt: Long)
@Entity("model_packs")
data class ModelPackEntity(@PrimaryKey val id: String, val name: String, val localPath: String, val installed: Boolean, val verified: Boolean, val loaded: Boolean = false)
@Entity("tts_engines")
data class TtsEngineEntity(@PrimaryKey val id: String, val name: String, val version: String, val localPath: String, val installed: Boolean, val verified: Boolean)
@Entity("voice_packs")
data class VoicePackEntity(@PrimaryKey val id: String, val name: String, val style: String, val language: String, val engine: String, val localPath: String, val modelPath: String, val tokensPath: String, val dataDirPath: String, val configPath: String, val licensePath: String, val attributionPath: String, val installed: Boolean, val verified: Boolean, val selected: Boolean)
@Entity("destinations")
data class DestinationEntity(@PrimaryKey val id: String, val name: String, val region: String, val country: String, val description: String, val heroImageLocalPath: String = "", val heroImageSourceUrl: String = "", val estimatedDriveMinutes: Int, val offlineSizeBytes: Long, val downloaded: Boolean, val createdAt: Long = System.currentTimeMillis(), val updatedAt: Long = System.currentTimeMillis())
@Entity("tour_packs")
data class TourPackEntity(@PrimaryKey val id: String, val destinationId: String, val name: String, val version: String, val localPath: String, val manifestPath: String, val downloaded: Boolean, val verified: Boolean, val sizeBytes: Long, val createdAt: Long = System.currentTimeMillis(), val updatedAt: Long = System.currentTimeMillis())
@Entity("routes")
data class RouteEntity(@PrimaryKey val id: String, val tourPackId: String, val name: String, val geoJsonPath: String, val estimatedDriveMinutes: Int)
@Entity("route_points")
data class RoutePointEntity(@PrimaryKey val id: String, val routeId: String, val sequence: Int, val latitude: Double, val longitude: Double)
@Entity("pois")
data class PoiEntity(@PrimaryKey val id: String, val tourPackId: String, val name: String, val type: String, val latitude: Double, val longitude: Double, val description: String, val imageLocalPath: String = "", val sourceIdsJson: String = "[]")
@Entity("story_triggers")
data class StoryTriggerEntity(@PrimaryKey val id: String, val tourPackId: String, val poiId: String, val latitude: Double, val longitude: Double, val radiusMeters: Double, val bearingStart: Double? = null, val bearingEnd: Double? = null, val priority: Int = 0, val cooldownMinutes: Long = 30, val storyId: String)
@Entity("stories")
data class StoryEntity(@PrimaryKey val id: String, val tourPackId: String, val title: String, val narrationText: String, val funFact: String = "", val imageLocalPath: String = "", val sourceIdsJson: String = "[]", val generatedByAi: Boolean = false, val createdAt: Long = System.currentTimeMillis())
@Entity("story_sources")
data class StorySourceEntity(@PrimaryKey val id: String, val storyId: String, val sourceType: String, val title: String, val url: String, val author: String = "", val license: String, val retrievedAt: Long = System.currentTimeMillis())
@Entity("downloads")
data class DownloadEntity(@PrimaryKey val id: String, val assetId: String, val status: String, val bytesDownloaded: Long = 0, val totalBytes: Long = 0, val workId: String = "", val error: String? = null, val startedAt: Long = System.currentTimeMillis(), val updatedAt: Long = System.currentTimeMillis())
@Entity("user_settings")
data class UserSettingsEntity(@PrimaryKey val id: Int = 1, val offlineOnly: Boolean = true, val wifiOnlyDownloads: Boolean = true, val selectedVoicePackId: String? = null, val narrationStyle: String = "friendly", val allowAndroidTtsFallback: Boolean = false, val kidFriendlyMode: Boolean = false, val responseLength: String = "short", val notificationsEnabled: Boolean = false, val telemetryEnabled: Boolean = false)
@Entity("ai_chat_messages")
data class AiChatMessageEntity(@PrimaryKey val id: String, val role: String, val content: String, val createdAt: Long = System.currentTimeMillis())
@Entity("app_events")
data class AppEventEntity(@PrimaryKey val id: String, val eventName: String, val detailsJson: String = "{}", val createdAt: Long = System.currentTimeMillis())
@Entity("narration_cache")
data class NarrationCacheEntity(@PrimaryKey val id: String, val storyId: String, val voicePackId: String, val audioPath: String, val createdAt: Long = System.currentTimeMillis())
